"""Optional isolated-copy cumulative negative controls; no production mutation."""
from pathlib import Path
from tempfile import TemporaryDirectory
import json,shutil,subprocess
root=Path(__file__).resolve().parents[4];report_dir=Path(__file__).resolve().parent
mutations=[('unconditional-duplicates', 'src/js/render/trail-system.js', 'spacingPx > 0 && this.pendingEmissions > 0', 'false && this.pendingEmissions > 0'), ('no-dpr-conversion', 'src/js/render/trail-system.js', 'spacingPx * (Number.isFinite(dpr) && dpr > 0 ? dpr : 1)', 'spacingPx'), ('reject-exact-threshold', 'src/js/render/trail-system.js', 'dx * dx + dy * dy >= thresholdSquared', 'dx * dx + dy * dy > thresholdSquared'), ('compare-oldest-history', 'src/js/render/trail-system.js', 'this.particles.tail?.particle', 'this.particles.head?.particle'), ('retain-whole-debt', 'src/js/render/trail-system.js', 'total % 1 : 0', 'total : 0'), ('old-emission-cap', 'src/js/core/particle-safety.js', 'limits.max, source[key]', 'key === "maxEmissionsPerFrame" ? 512 : limits.max, source[key]'), ('old-retention-cap', 'src/js/render/particle-governor.js', 'this.#policy = Object.freeze(normalizeParticleSafety(policy));', 'this.#policy = Object.freeze({...normalizeParticleSafety(policy), maxActiveParticles: Math.min(16384, normalizeParticleSafety(policy).maxActiveParticles)});'), ('governor-recreation', 'src/js/render/visualizer-runtime.js', 'const particleGovernor = new ParticleGovernor', 'let particleGovernor = new ParticleGovernor'), ('missing-retention-trim', 'src/js/render/particle-governor.js', 'while (this.heap.length > next.maxActiveParticles)', 'while (false && this.heap.length > next.maxActiveParticles)'), ('stale-runtime-policy', 'src/js/render/visualizer-runtime.js', 'return particleGovernor.applyPolicy(source);', 'return false;'), ('incorrect-zero-retention', 'src/js/render/particle-governor.js', 'if (this.policy.maxActiveParticles === 0) return false;', 'if (false) return false;'), ('persist-runtime-counter', 'src/js/presets/preset-codec.js', 'next.particleSafety = normalizeParticleSafety(incoming.particleSafety);', 'next.particleSafety = {...normalizeParticleSafety(incoming.particleSafety), emissions: 0};'), ('capped-orb-motion', 'src/js/render/orb.js', 'this.motion.angularSpeedRadPerSec * motionDtSec;', 'this.motion.angularSpeedRadPerSec * dtSec;'), ('unbounded-motion-catchup', 'src/js/core/timing.js', 'elapsedSec <= CONFIG.limits.timing.motionDiscontinuitySec ? elapsedSec : 0', 'true ? elapsedSec : 0'), ('unbounded-emission-delta', 'src/js/main.js', 'simulationDeltaSec(elapsedSec, runtime.settings.timing?.maxDeltaTimeSec) : 0', 'elapsedSec : 0'), ('full-trail-expiry-scan', 'src/js/render/trail-system.js', 'else if (ordered) break;', 'else if (false) break;'), ('incorrect-unordered-early-exit', 'src/js/render/trail-system.js', 'const ordered = this.particles.birthOrderMonotonic;', 'const ordered = true;'), ('broken-retirement-ownership', 'src/js/render/particle-governor.js', 'node.heapIndex = -1;', 'node.heapIndex = 0;'), ('stale-diagnostics', 'src/js/ui/scene-panel.js', 'refreshDiagnostics();\n    if (!settings || settings === lastSettingsRef) return false;', 'if (!settings || settings === lastSettingsRef) return false;\n    refreshDiagnostics();'), ('free-ring-pause-ignored', 'src/js/render/visualizer-runtime.js', '} else if (!simPaused) {', '} else {'), ('youngest-first-eviction', 'src/js/render/particle-governor.js', 'a.particle.bornSec < b.particle.bornSec', 'a.particle.bornSec > b.particle.bornSec'), ('spacing-consumes-allocation', 'src/js/render/particle-governor.js', 'while (head && remaining > 0)', 'remaining -= this.stats.spatiallyRejectedDemand;\n    while (head && remaining > 0)'), ('lost-fair-priority', 'src/js/render/particle-governor.js', 'this.servicePriority(trail);', '// priority mutation')]
results=[]
with TemporaryDirectory(prefix='auralprint-final-mutations-') as directory:
 checkout=Path(directory);shutil.copytree(root/'src',checkout/'src');shutil.copytree(root/'tests',checkout/'tests')
 for name,relative,before,after in mutations:
  source=checkout/relative;original=source.read_text();assert before in original,name;mutated=original.replace(before,after)
  if name=='governor-recreation':mutated=mutated.replace('return particleGovernor.applyPolicy(source);','particleGovernor.dispose();particleGovernor = new ParticleGovernor(source);return true;')
  source.write_text(mutated)
  try:
   command=['node','--test','--test-isolation=none','tests/rc15-spacing.test.js','tests/rc15-budgets.test.js','tests/rc15-timing-performance.test.js','tests/rc15-phase2.test.js','tests/rc15-integrated-review.test.js','tests/scene-panel.test.js']
   if name=='governor-recreation':command=['node','--test','--test-isolation=none','--test-name-pattern=budgets: runtime synchronization','tests/rc15-budgets.test.js']
   run=subprocess.run(command,cwd=checkout,text=True,capture_output=True,timeout=60)
   output=run.stdout+run.stderr;lines=output.splitlines();failed=[line for line in lines if line.startswith('✖') or 'not ok' in line or 'AssertionError' in line or 'TypeError' in line]
   (report_dir/f'mutation-{name}.log').write_text('\n'.join(line.rstrip() for line in failed+lines[-15:])+'\n')
   results.append({'mutation':name,'detected':run.returncode!=0 and ('AssertionError' in output or 'TypeError' in output) and 'SyntaxError' not in output,'exitCode':run.returncode,'failingChecks':failed[:12]})
  finally:source.write_text(original)
(report_dir/'mutations.json').write_text(json.dumps(results,indent=2)+'\n');print(json.dumps(results,indent=2));assert all(r['detected'] for r in results)
